css:
.p36-geartip { position: absolute; right: 0; top: calc(100% + var(--s-1)); z-index: 30; white-space: nowrap; }
.p36-menutip { display: block; max-width: none; padding: var(--s-2) var(--s-3) var(--s-1); border: 0; border-top: var(--w1) solid var(--rule); border-radius: 0; font-weight: var(--fw-regular); color: var(--muted); }
.p36-hover { text-decoration: underline; text-underline-offset: 0.25em; }
.p36-focus { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.p36-top { margin-bottom: var(--s-3); }
.dialog__foot.p36-foot { flex-direction: column; }
.p36-foot > * { flex: none; }
.p35-form { display: grid; gap: var(--s-4); }
.p35-cols { display: grid; gap: var(--s-4); grid-template-columns: minmax(0, 1fr); align-items: start; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p35-cols { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--s-5); } }
.p35-col { display: grid; gap: var(--s-4); align-content: start; min-width: 0; }
.p35-sec { display: grid; gap: var(--s-2); min-width: 0; }
.p35-radios { display: grid; }
.p35-cap { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p35-expl { display: block; font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); }
.p35-cat { cursor: pointer; }
.p35-cat .rec__title { display: block; }
.p35-cat .rec__lead .check { min-height: var(--hit); }
.p35-hint { font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); padding-inline-start: calc(1.125rem + var(--s-2)); margin-top: calc(var(--s-1) * -1); }
.p35-note { display: grid; gap: var(--s-1); padding: var(--s-2) 0; }
.p35-status { display: flex; align-items: center; gap: var(--s-2); padding: var(--s-4) 0; }
.p35-err { display: grid; gap: var(--s-3); justify-items: start; padding: var(--s-2) 0; }
.p35-err .banner { width: 100%; }
.p35-actions { position: sticky; bottom: 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2); padding: var(--s-3); margin: var(--s-4) calc(var(--s-3) * -1) calc(var(--s-3) * -1); background: var(--white); border-top: var(--w1) solid var(--rule); z-index: 2; }
.p35-actions__right { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--s-2); margin-inline-start: auto; }
.p35-applywrap { position: relative; display: inline-block; }
.p35-tip { position: absolute; right: 0; bottom: calc(100% + var(--s-2)); white-space: nowrap; z-index: 6; }
.p35-actions .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p35-rules { display: grid; gap: var(--s-2); }
.p35-rule-over { min-height: 7rem; }
.p36-e { --frame-w: var(--w2); }

.p36-ios .dialog__body { padding-bottom: var(--s-4); }
.p36-steps { list-style: decimal; padding-inline-start: var(--s-4); display: grid; gap: var(--s-2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
.menu-pop .menu { top: calc(100% + var(--s-3)); }
